'use strict'
// Original offline producer -> current server parser -> protected first-upload
// contract. Executes actual repository source, fictional generated bytes only.
const test = require('node:test')
const assert = require('node:assert/strict')
const fs = require('node:fs')
const os = require('node:os')
const path = require('node:path')
const vm = require('node:vm')
const { pathToFileURL } = require('node:url')
const { createHash } = require('node:crypto')
const { spawnSync } = require('node:child_process')
const ts = require('typescript')
const { makeFixture } = require('../scripts/first-memory-authenticated-emulator-journey.cjs')
const sha = bytes => createHash('sha256').update(bytes).digest('hex')
const root = path.resolve(__dirname, '../../..')
const offlineScript = pathToFileURL(path.join(root, 'urai-tier1/scripts/prepare-first-private-memory.mjs')).href
const loadSource = file => {
  const source = fs.readFileSync(path.join(__dirname, '../src', file), 'utf8')
  const output = ts.transpileModule(source, { compilerOptions: { module: ts.ModuleKind.CommonJS,
    target: ts.ScriptTarget.ES2022, esModuleInterop: true } }).outputText
  const scope = { exports: {} }
  vm.runInNewContext(output, { module: scope, exports: scope.exports, require, Buffer, Date })
  return scope.exports
}
const { parsePreparedFirstPrivateMemory } = loadSource('firstPrivateMemoryPacket.ts')
const { assertPreparedPrivateMediaFirstUpload } = loadSource('privatePreparedMediaAuthority.ts')
const uid='syntheticOwner', memoryId='syntheticMemory'
const build = async bytes => {
  const dir=fs.mkdtempSync(path.join(os.tmpdir(), 'urai-firstlife-original-codec-'))
  const originalPath=path.join(dir,'fictional-original.mp3'), sourcePath=path.join(dir,'fictional-derivative.ogg')
  fs.writeFileSync(originalPath,Buffer.from('ID3 Fictional record, no user memories or identities.'))
  fs.writeFileSync(sourcePath,bytes)
  try {
    const { prepareFirstPrivateMemory } = await import(offlineScript)
    return await prepareFirstPrivateMemory({ownerId:uid,memoryId,originalPath,sourcePath,
      sourceRef:'offline:fictional-source-test',occurredAt:'2026-11-06T00:00:00.000Z',
      occurredAtBasis:'archive-time-proxy-not-capture-date',durationMs:6000,
      title:'Fictional source recording',summary:'Original six-second synthetic tone only; no person or events.'})
  } finally {fs.rmSync(dir,{recursive:true,force:true})}
}
test('generated six-second Opus is deterministic, encoded and exactly decodable', () => {
  const a=makeFixture(uid,memoryId).audio, b=makeFixture(uid,memoryId).audio
  assert.deepEqual(a,b)
  assert.equal(a.toString('ascii',0,4),'OggS')
  assert.ok(a.subarray(0,128).includes(Buffer.from('OpusHead')))
  const probed=spawnSync('ffprobe',['-v','error','-show_entries','stream=codec_name','-of','json','pipe:0'],
    {input:a,encoding:'utf8',timeout:15000})
  assert.equal(probed.status,0,String(probed.stderr))
  assert.ok(JSON.parse(probed.stdout).streams.some(x=>x.codec_name==='opus'))
  const decoded=spawnSync('ffmpeg',['-hide_banner','-loglevel','error','-nostdin','-i','pipe:0',
    '-ar','16000','-ac','1','-f','s16le','pipe:1'],{input:a,timeout:15000,maxBuffer:1024*1024})
  assert.equal(decoded.status,0,String(decoded.stderr))
  assert.equal(decoded.stdout.length,6*16000*2)
})
test('same original Opus passes producer, parser and first-upload authority', async () => {
  const fixture=makeFixture(uid,memoryId), packet=await build(fixture.audio)
  assert.equal(packet.upload.sha256,sha(fixture.audio))
  assert.equal(packet.upload.fileByteLength,fixture.audio.length)
  assert.equal(packet.upload.offlinePreparationGrantsConsent,false)
  assert.equal(Object.hasOwn(packet.memory,'consentState'),false)
  const parsed=parsePreparedFirstPrivateMemory(packet,uid)
  assert.equal(parsed.memory.ownerId,uid)
  assert.equal(parsed.memory.consentState,'authorized')
  assert.equal(parsed.memory.privacy,'hidden')
  assert.deepEqual(Array.from(parsed.memory.sourceMedia),[])
  assert.doesNotThrow(()=>assertPreparedPrivateMediaFirstUpload(parsed.memory,uid,memoryId,
    packet.upload.request.operationId,'audio','audio/ogg',sha(fixture.audio),fixture.audio.length))
  assert.equal(packet.upload.request.operationId, fixture.operationId)
})
test('legacy Vorbis fixture cannot be passed off as a valid original offline input', async () => {
  const generated=spawnSync('ffmpeg',['-hide_banner','-loglevel','error','-nostdin','-f','lavfi',
    '-i','sine=frequency=440:sample_rate=16000:duration=6','-ac','1','-c:a','libvorbis','-q:a','-1',
    '-map_metadata','-1','-f','ogg','pipe:1'],{timeout:15000,maxBuffer:1024*1024})
  assert.equal(generated.status,0,String(generated.stderr))
  assert.equal(generated.stdout.toString('ascii',0,4),'OggS')
  await assert.rejects(build(generated.stdout),/SOURCE_FORMAT_UNSUPPORTED_FOR_OWNED_MEMORY_MEDIA/)
})
test('original server parser still denies foreign identity and wrong digest', async () => {
  const fixture=makeFixture(uid,memoryId), packet=await build(fixture.audio)
  assert.throws(()=>parsePreparedFirstPrivateMemory(packet,'foreignOwner'),/FIRST_PRIVATE_MEMORY_PACKET_INVALID/)
  const wrong=structuredClone(packet);wrong.upload.sha256='f'.repeat(64)
  assert.throws(()=>parsePreparedFirstPrivateMemory(wrong,uid),/FIRST_PRIVATE_MEMORY_PACKET_INVALID/)
})
